diff --git a/frontend/app/lib/api/user/recipes/recipe.test.ts b/frontend/app/lib/api/user/recipes/recipe.test.ts
new file mode 100644
index 0000000..4e16728
--- /dev/null
+++ b/frontend/app/lib/api/user/recipes/recipe.test.ts
@@ -0,0 +1,239 @@
+import { describe, expect, test, vi, beforeEach, afterEach } from "vitest";
+
+type Listener = (e: any) => void;
+
+// Fake mirroring sse.js 2.8.0 semantics: close() sets readyState to CLOSED and re-dispatches
+// "readystatechange" (with .readyState) and "abort" synchronously, like xhr.abort() does.
+const { FakeSSE } = vi.hoisted(() => {
+  class FakeSSE {
+    static CLOSED = 2;
+    static instances: FakeSSE[] = [];
+
+    readyState = 1;
+    closeCalls = 0;
+    streamCalls = 0;
+    listeners: Record<string, Listener[]> = {};
+
+    constructor(public url: string, public options: any) {
+      FakeSSE.instances.push(this);
+    }
+
+    addEventListener(type: string, fn: Listener) {
+      (this.listeners[type] ??= []).push(fn);
+    }
+
+    stream() {
+      this.streamCalls++;
+    }
+
+    emit(type: string, extra: Record<string, unknown> = {}) {
+      for (const fn of this.listeners[type] ?? []) {
+        fn({ type, ...extra });
+      }
+    }
+
+    close() {
+      this.closeCalls++;
+      this.readyState = FakeSSE.CLOSED;
+      this.emit("abort");
+      this.emit("readystatechange", { readyState: FakeSSE.CLOSED });
+    }
+  }
+  return { FakeSSE };
+});
+
+vi.mock("sse.js", () => ({ SSE: FakeSSE }));
+
+import { RecipeAPI, RECIPE_CREATE_FAILED_MESSAGE } from "./recipe";
+
+function lastSse() {
+  return FakeSSE.instances[FakeSSE.instances.length - 1]!;
+}
+
+function start(onProgress?: (m: string) => void) {
+  const api = new RecipeAPI({} as any);
+  const promise = api.createOneByUrl("https://example.com/r", true, false, onProgress);
+  const settled = vi.fn();
+  promise.then(settled);
+  return { promise, settled, sse: lastSse() };
+}
+
+async function flush() {
+  await Promise.resolve();
+  await Promise.resolve();
+}
+
+describe("RecipeAPI streamed recipe creation", () => {
+  beforeEach(() => {
+    FakeSSE.instances = [];
+    vi.stubGlobal("useMealieAuth", () => ({ token: { value: "tok" } }));
+  });
+
+  afterEach(() => {
+    vi.unstubAllGlobals();
+  });
+
+  test("opens the stream with auth header, JSON payload and no auto reconnect", () => {
+    const { sse } = start();
+    expect(sse.url).toBe("/api/recipes/create/url/stream");
+    expect(sse.streamCalls).toBe(1);
+    expect(sse.options.autoReconnect).toBe(false);
+    expect(sse.options.headers.Authorization).toBe("Bearer tok");
+    expect(JSON.parse(sse.options.payload)).toEqual({ url: "https://example.com/r", includeTags: true, includeCategories: false });
+  });
+
+  test("done resolves with the slug and closes the stream once", async () => {
+    const { promise, sse, settled } = start();
+    sse.emit("done", { data: JSON.stringify({ slug: "my-recipe" }) });
+
+    const result = await promise;
+    expect(result.error).toBeNull();
+    expect(result.data).toBe("my-recipe");
+    expect(result.response?.status).toBe(201);
+    expect(sse.closeCalls).toBe(1);
+
+    // trailing events (including those re-fired by close()) must not change anything
+    sse.emit("error", { data: JSON.stringify({ message: "late" }) });
+    sse.emit("abort");
+    sse.emit("readystatechange", { readyState: FakeSSE.CLOSED });
+    await flush();
+    expect(sse.closeCalls).toBe(1);
+    expect(settled).toHaveBeenCalledTimes(1);
+    expect(settled.mock.calls[0]![0].data).toBe("my-recipe");
+  });
+
+  test.each([
+    ["not JSON", "garbage"],
+    ["missing slug", JSON.stringify({})],
+    ["empty slug", JSON.stringify({ slug: "" })],
+    ["non-string slug", JSON.stringify({ slug: 5 })],
+  ])("done with %s fails with the generic message and closes", async (_name, data) => {
+    const { promise, sse } = start();
+    sse.emit("done", { data });
+
+    const result = await promise;
+    expect(result.data).toBeNull();
+    expect(result.error?.message).toBe(RECIPE_CREATE_FAILED_MESSAGE);
+    expect(sse.closeCalls).toBe(1);
+  });
+
+  test("error with backend message surfaces it, closes once, ignores re-fired abort/readystatechange", async () => {
+    const { promise, sse, settled } = start();
+    sse.emit("error", { data: JSON.stringify({ message: "Could not scrape" }) });
+
+    const result = await promise;
+    expect(result.data).toBeNull();
+    expect(result.response).toBeNull();
+    expect(result.error?.message).toBe("Could not scrape");
+    expect(sse.closeCalls).toBe(1);
+
+    await flush();
+    expect(settled).toHaveBeenCalledTimes(1);
+    expect(settled.mock.calls[0]![0].error.message).toBe("Could not scrape");
+  });
+
+  test.each([
+    ["non-JSON text", "connection refused"],
+    ["empty data", ""],
+    ["JSON without message", JSON.stringify({ detail: "x" })],
+    ["blank message", JSON.stringify({ message: "   " })],
+    ["non-string message", JSON.stringify({ message: 42 })],
+    ["JSON null", "null"],
+  ])("error with %s falls back to the generic message", async (_name, data) => {
+    const { promise, sse } = start();
+    sse.emit("error", { data });
+
+    const result = await promise;
+    expect(result.error?.message).toBe(RECIPE_CREATE_FAILED_MESSAGE);
+    expect(sse.closeCalls).toBe(1);
+  });
+
+  test("error with undefined data falls back to the generic message", async () => {
+    const { promise, sse } = start();
+    sse.emit("error");
+    const result = await promise;
+    expect(result.error?.message).toBe(RECIPE_CREATE_FAILED_MESSAGE);
+    expect(sse.closeCalls).toBe(1);
+  });
+
+  test("silent close (readystatechange CLOSED, no data events) fails and closes once", async () => {
+    const { promise, sse, settled } = start();
+    sse.readyState = FakeSSE.CLOSED;
+    sse.emit("readystatechange", { readyState: FakeSSE.CLOSED });
+
+    const result = await promise;
+    expect(result.data).toBeNull();
+    expect(result.error?.message).toBe(RECIPE_CREATE_FAILED_MESSAGE);
+    expect(sse.closeCalls).toBe(1);
+
+    await flush();
+    expect(settled).toHaveBeenCalledTimes(1);
+  });
+
+  test("readystatechange for a non-closed state does not settle", async () => {
+    const { sse, settled } = start();
+    sse.emit("readystatechange", { readyState: 1 });
+    await flush();
+    expect(settled).not.toHaveBeenCalled();
+    expect(sse.closeCalls).toBe(0);
+  });
+
+  test("abort alone fails and closes once", async () => {
+    const { promise, sse } = start();
+    sse.emit("abort");
+
+    const result = await promise;
+    expect(result.error?.message).toBe(RECIPE_CREATE_FAILED_MESSAGE);
+    expect(sse.closeCalls).toBe(1);
+  });
+
+  test("done arriving before the trailing close wins over the silent-close failure", async () => {
+    const { promise, sse } = start();
+    sse.emit("done", { data: JSON.stringify({ slug: "ok" }) });
+    sse.emit("readystatechange", { readyState: FakeSSE.CLOSED });
+
+    const result = await promise;
+    expect(result.data).toBe("ok");
+    expect(sse.closeCalls).toBe(1);
+  });
+
+  test("progress messages are forwarded until settled; malformed ones are ignored", async () => {
+    const onProgress = vi.fn();
+    const { promise, sse } = start(onProgress);
+
+    sse.emit("progress", { data: JSON.stringify({ message: "Scraping" }) });
+    sse.emit("progress", { data: "not json" });
+    expect(onProgress).toHaveBeenCalledTimes(1);
+    expect(onProgress).toHaveBeenCalledWith("Scraping");
+    expect(sse.closeCalls).toBe(0);
+
+    sse.emit("done", { data: JSON.stringify({ slug: "s" }) });
+    sse.emit("progress", { data: JSON.stringify({ message: "after" }) });
+    await promise;
+    expect(onProgress).toHaveBeenCalledTimes(1);
+  });
+
+  test("no progress listener is registered without a callback", () => {
+    const { sse } = start();
+    expect(sse.listeners["progress"]).toBeUndefined();
+  });
+
+  test("html-or-json variant uses its stream route and settles the same way", async () => {
+    const api = new RecipeAPI({} as any);
+    const promise = api.createOneByHtmlOrJson("<html/>", false, true, "https://x.y");
+    const sse = lastSse();
+    expect(sse.url).toBe("/api/recipes/create/html-or-json/stream");
+    expect(JSON.parse(sse.options.payload)).toEqual({ data: "<html/>", includeTags: false, includeCategories: true, url: "https://x.y" });
+
+    sse.emit("error", { data: JSON.stringify({ message: "bad html" }) });
+    const result = await promise;
+    expect(result.error?.message).toBe("bad html");
+    expect(sse.closeCalls).toBe(1);
+  });
+
+  test("omits Authorization header when there is no token", () => {
+    vi.stubGlobal("useMealieAuth", () => ({ token: { value: null } }));
+    const { sse } = start();
+    expect(sse.options.headers.Authorization).toBeUndefined();
+  });
+});
diff --git a/frontend/app/lib/api/user/recipes/recipe.ts b/frontend/app/lib/api/user/recipes/recipe.ts
index 70ae3aa..7d4ebbb 100644
--- a/frontend/app/lib/api/user/recipes/recipe.ts
+++ b/frontend/app/lib/api/user/recipes/recipe.ts
@@ -31,6 +31,11 @@ export interface CreateAsset {
   file: File;
 }

+export const RECIPE_CREATE_FAILED_MESSAGE = "Recipe creation failed";
+
+// sse.js readyState value for a closed stream (SSE.CLOSED)
+const SSE_CLOSED = 2;
+
 const prefix = "/api";

 const routes = {
@@ -164,29 +169,72 @@ export class RecipeAPI extends BaseCRUDAPI<CreateRecipe, Recipe, Recipe> {
         autoReconnect: false,
       });

+      // Settle exactly once and always close the stream. sse.close() aborts the XHR, which
+      // re-dispatches "abort" and "readystatechange"; the flag makes those no-ops.
+      let settled = false;
+      const settle = (result: RequestResponse<string>) => {
+        if (settled) {
+          return;
+        }
+        settled = true;
+        sse.close();
+        resolve(result);
+      };
+      const fail = (message: string = RECIPE_CREATE_FAILED_MESSAGE) =>
+        settle({ response: null, data: null, error: new Error(message) });
+
       if (onProgress) {
         sse.addEventListener(SSEDataEventStatus.Progress, (e: SSEvent) => {
-          const { message } = JSON.parse(e.data) as SSEDataEventMessage;
-          onProgress(message);
+          if (settled) {
+            return;
+          }
+          try {
+            const { message } = JSON.parse(e.data) as SSEDataEventMessage;
+            onProgress(message);
+          }
+          catch {
+            // Malformed progress payloads are cosmetic; keep waiting for done/error
+          }
         });
       }

       sse.addEventListener(SSEDataEventStatus.Done, (e: SSEvent) => {
-        const { slug } = JSON.parse(e.data) as SSEDataEventDone;
-        sse.close();
-        resolve({ response: { status: 201, data: slug } as any, data: slug, error: null });
+        try {
+          const { slug } = JSON.parse(e.data) as SSEDataEventDone;
+          if (typeof slug !== "string" || !slug) {
+            fail();
+            return;
+          }
+          settle({ response: { status: 201, data: slug } as any, data: slug, error: null });
+        }
+        catch {
+          fail();
+        }
       });

       sse.addEventListener(SSEDataEventStatus.Error, (e: SSEvent) => {
+        // Backend errors carry {"message": "<reason>"}; transport errors carry anything else.
+        let message = RECIPE_CREATE_FAILED_MESSAGE;
         try {
-          const { message } = JSON.parse(e.data) as SSEDataEventMessage;
-          sse.close();
-          resolve({ response: null, data: null, error: new Error(message) });
+          const parsed = JSON.parse(e.data) as Partial<SSEDataEventMessage> | null;
+          if (typeof parsed?.message === "string" && parsed.message.trim()) {
+            message = parsed.message;
+          }
         }
         catch {
-          // Not a backend error payload (e.g. XHR connection-close event); ignore
+          // Not JSON: use the fallback message
+        }
+        fail(message);
+      });
+
+      // Verified against sse.js 2.8.0 (lib/sse.js): the stream ends with a "readystatechange"
+      // event (readyState SSE.CLOSED === 2) after all data events, and "abort" on xhr.abort().
+      sse.addEventListener("readystatechange", (e: SSEvent) => {
+        if (((e as unknown as { readyState?: number }).readyState ?? sse.readyState) === SSE_CLOSED) {
+          fail();
         }
       });
+      sse.addEventListener("abort", () => fail());

       sse.stream();
     });
