--- /dev/null
+++ b/src/diet.js
@@ -0,0 +1,38 @@
+'use strict';
+
+// Pure diet helpers. Maps/Sets only: food and label names come from Mealie
+// and must never be used as plain-object keys.
+
+const normFood = (s) => s.trim().replace(/\s+/g, ' ').toLowerCase();
+const normLabel = (s) => s.trim().toLowerCase();
+
+const BANNED_LABELS = new Map([
+  ['vegetarian', ['meat', 'fish']],
+  ['vegan', ['meat', 'fish', 'dairy', 'egg']],
+  ['gluten-free', ['gluten']],
+]);
+
+// Union of banned (normalised) labels for the given diets; unknown diets ignored.
+function bannedSet(diets) {
+  const out = new Set();
+  for (const d of Array.isArray(diets) ? diets : []) {
+    const labels = BANNED_LABELS.get(d);
+    if (labels) for (const l of labels) out.add(l);
+  }
+  return out;
+}
+
+// labelByFood: Map<normFood(name), label name>. Missing data is never a violation.
+function recipeViolatesDiet(ingredients, labelByFood, banned) {
+  if (!Array.isArray(ingredients) || banned.size === 0) return false;
+  for (const ing of ingredients) {
+    const name = ing && ing.food && typeof ing.food.name === 'string' ? ing.food.name : '';
+    const food = normFood(name);
+    if (food === '') continue;
+    const label = labelByFood.get(food);
+    if (typeof label === 'string' && banned.has(normLabel(label))) return true;
+  }
+  return false;
+}
+
+module.exports = { BANNED_LABELS, bannedSet, recipeViolatesDiet, normFood, normLabel };
