+++ b/test/diet.test.js
@@ -0,0 +1,83 @@
+'use strict';
+// Pure diet helpers (src/diet.js).
+
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const { BANNED_LABELS, bannedSet, recipeViolatesDiet, normFood, normLabel } = require('../src/diet');
+
+const ing = (name) => ({ food: name === null ? null : { name } });
+const labels = (pairs) => new Map(pairs);
+
+test('ban table per diet', () => {
+  assert.deepEqual(BANNED_LABELS.get('vegetarian'), ['meat', 'fish']);
+  assert.deepEqual(BANNED_LABELS.get('vegan'), ['meat', 'fish', 'dairy', 'egg']);
+  assert.deepEqual(BANNED_LABELS.get('gluten-free'), ['gluten']);
+  assert.equal(BANNED_LABELS.size, 3);
+});
+
+test('bannedSet: per diet, union, unknown and non-array ignored', () => {
+  assert.deepEqual([...bannedSet(['vegetarian'])].sort(), ['fish', 'meat']);
+  assert.deepEqual([...bannedSet(['vegan'])].sort(), ['dairy', 'egg', 'fish', 'meat']);
+  assert.deepEqual([...bannedSet(['gluten-free'])], ['gluten']);
+  assert.deepEqual([...bannedSet(['vegetarian', 'gluten-free'])].sort(), ['fish', 'gluten', 'meat']);
+  assert.deepEqual([...bannedSet(['vegan', 'vegetarian'])].sort(), ['dairy', 'egg', 'fish', 'meat']);
+  assert.equal(bannedSet(['keto']).size, 0);
+  assert.equal(bannedSet(['__proto__', 'constructor', 'toString']).size, 0);
+  assert.equal(bannedSet([]).size, 0);
+  assert.equal(bannedSet(undefined).size, 0);
+  assert.equal(bannedSet('vegan').size, 0);
+});
+
+test('normFood / normLabel', () => {
+  assert.equal(normFood('  Soy   SAUCE\t'), 'soy sauce');
+  assert.equal(normFood('   '), '');
+  assert.equal(normLabel('  MeAt '), 'meat');
+  assert.equal(normLabel('a  b'), 'a  b'); // labels: trim + lowercase only
+});
+
+test('recipeViolatesDiet: violation per diet', () => {
+  const l = labels([['chicken', 'Meat'], ['cod', 'Fish'], ['milk', 'Dairy'], ['eggs', 'Egg'], ['flour', 'Gluten'], ['rice', 'Grain']]);
+  assert.equal(recipeViolatesDiet([ing('Chicken')], l, bannedSet(['vegetarian'])), true);
+  assert.equal(recipeViolatesDiet([ing('Cod')], l, bannedSet(['vegetarian'])), true);
+  assert.equal(recipeViolatesDiet([ing('Milk')], l, bannedSet(['vegetarian'])), false);
+  assert.equal(recipeViolatesDiet([ing('Milk')], l, bannedSet(['vegan'])), true);
+  assert.equal(recipeViolatesDiet([ing('Eggs')], l, bannedSet(['vegan'])), true);
+  assert.equal(recipeViolatesDiet([ing('Flour')], l, bannedSet(['gluten-free'])), true);
+  assert.equal(recipeViolatesDiet([ing('Flour')], l, bannedSet(['vegan'])), false);
+  assert.equal(recipeViolatesDiet([ing('Rice'), ing('Flour')], l, bannedSet(['gluten-free'])), true);
+  assert.equal(recipeViolatesDiet([ing('Rice')], l, bannedSet(['vegan'])), false);
+});
+
+test('recipeViolatesDiet: label case/whitespace and food name variants', () => {
+  const banned = bannedSet(['vegetarian']);
+  for (const lab of ['meat', 'MEAT', '  Meat  ', 'mEaT\t']) {
+    assert.equal(recipeViolatesDiet([ing('beef')], labels([['beef', lab]]), banned), true, JSON.stringify(lab));
+  }
+  assert.equal(recipeViolatesDiet([ing('  BEEF   Steak ')], labels([['beef steak', 'Meat']]), banned), true);
+  assert.equal(recipeViolatesDiet([ing('beef')], labels([['beef', 'meatballs']]), banned), false);
+});
+
+test('recipeViolatesDiet: missing data is never a violation', () => {
+  const banned = bannedSet(['vegan']);
+  const l = labels([['beef', 'Meat'], ['plain', null], ['odd', 5]]);
+  assert.equal(recipeViolatesDiet([ing('unlisted')], l, banned), false, 'food not in list');
+  assert.equal(recipeViolatesDiet([ing('plain')], l, banned), false, 'label null');
+  assert.equal(recipeViolatesDiet([ing('odd')], l, banned), false, 'label non-string');
+  assert.equal(recipeViolatesDiet([ing(null)], l, banned), false, 'ingredient without food');
+  assert.equal(recipeViolatesDiet([{}, null, undefined, { food: { name: 5 } }, { food: {} }, { food: { name: '  ' } }], l, banned), false);
+  assert.equal(recipeViolatesDiet([], l, banned), false, 'no ingredients');
+  assert.equal(recipeViolatesDiet(undefined, l, banned), false);
+  assert.equal(recipeViolatesDiet(null, l, banned), false);
+  assert.equal(recipeViolatesDiet('x', l, banned), false);
+  assert.equal(recipeViolatesDiet([ing('beef')], l, new Set()), false, 'empty banned set');
+  assert.equal(recipeViolatesDiet([ing('beef')], new Map(), banned), false, 'empty label map');
+});
+
+test('recipeViolatesDiet: __proto__ and prototype-named foods are safe', () => {
+  const banned = bannedSet(['vegan']);
+  assert.equal(recipeViolatesDiet([ing('__proto__'), ing('constructor'), ing('toString')], new Map(), banned), false);
+  const l = labels([['__proto__', 'Meat']]);
+  assert.equal(recipeViolatesDiet([ing('__PROTO__')], l, banned), true);
+  assert.equal(recipeViolatesDiet([ing('constructor')], l, banned), false);
+  assert.equal(({}).polluted, undefined);
+});
