@@ -0,0 +1,219 @@
+'use strict';
+// Households (w3): real HTTP server on an ephemeral port, real SQLite, fake Mealie.
+
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const http = require('node:http');
+const { startFake, makeRecipes } = require('./helpers/fakeMealie');
+const { openDb } = require('../src/db');
+const { migrate } = require('../src/migrate');
+const { createStore } = require('../src/store');
+const { createMealieClient } = require('../src/mealie');
+const { createServer } = require('../src/server');
+
+function call(base, method, p, body) {
+  return new Promise((resolve, reject) => {
+    const u = new URL(base + p);
+    const req = http.request({ hostname: u.hostname, port: u.port, path: u.pathname + u.search, method, agent: false }, (res) => {
+      const chunks = [];
+      res.on('data', (c) => chunks.push(c));
+      res.on('end', () => {
+        const text = Buffer.concat(chunks).toString('utf8');
+        let json;
+        try { json = JSON.parse(text); } catch { json = undefined; }
+        resolve({ status: res.statusCode, headers: res.headers, text, json });
+      });
+    });
+    req.on('error', reject);
+    if (body !== undefined) req.write(typeof body === 'string' ? body : JSON.stringify(body));
+    req.end();
+  });
+}
+
+async function withEnv(fn) {
+  const fake = await startFake({ recipes: makeRecipes(8) });
+  const db = openDb(':memory:');
+  migrate(db);
+  const server = createServer({ store: createStore(db), mealie: createMealieClient({ baseUrl: fake.url }) });
+  await new Promise((r) => server.listen(0, '127.0.0.1', r));
+  const base = `http://127.0.0.1:${server.address().port}`;
+  const app = {
+    fake,
+    db,
+    count: (t) => db.prepare(`SELECT count(*) AS c FROM ${t}`).get().c,
+    req: (m, p, b) => call(base, m, p, b),
+    mkHousehold: async (name = 'Smiths') => (await call(base, 'POST', '/households', { name })).json,
+    mkPlan: (body) => call(base, 'POST', '/plans', { weekStart: '2025-01-06', days: 1, ...body }),
+  };
+  try {
+    await fn(app);
+  } finally {
+    server.closeAllConnections();
+    await new Promise((r) => server.close(r));
+    db.close();
+    await fake.close();
+  }
+}
+
+const NAME_MSG = 'name: required, non-empty string up to 200 characters';
+
+test('POST /households: 201 {id,name}, uuid, trimmed, stored, GET returns it; duplicates allowed', () =>
+  withEnv(async (app) => {
+    const r = await app.req('POST', '/households', { name: '  The Smiths  ' });
+    assert.equal(r.status, 201);
+    assert.match(r.headers['content-type'], /application\/json/);
+    assert.deepEqual(Object.keys(r.json).sort(), ['id', 'name']);
+    assert.match(r.json.id, /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/);
+    assert.equal(r.json.name, 'The Smiths');
+    const g = await app.req('GET', `/households/${r.json.id}`);
+    assert.equal(g.status, 200);
+    assert.deepEqual(g.json, r.json);
+    const r2 = await app.req('POST', '/households', { name: 'The Smiths' });
+    assert.equal(r2.status, 201);
+    assert.notEqual(r2.json.id, r.json.id);
+    assert.equal(app.count('households'), 2);
+    assert.equal((await app.req('POST', '/households', { name: 'x'.repeat(200) })).status, 201);
+  }));
+
+test('POST /households: bad bodies -> 400, nothing stored', () =>
+  withEnv(async (app) => {
+    const rows = [
+      ['missing name', {}, NAME_MSG],
+      ['empty', { name: '' }, NAME_MSG],
+      ['blank', { name: '   ' }, NAME_MSG],
+      ['number', { name: 5 }, NAME_MSG],
+      ['null', { name: null }, NAME_MSG],
+      ['array', { name: ['a'] }, NAME_MSG],
+      ['object', { name: { a: 1 } }, NAME_MSG],
+      ['201 chars', { name: 'x'.repeat(201) }, NAME_MSG],
+      ['array body', [], 'body: must be a JSON object'],
+      ['null body', 'null', 'body: must be a JSON object'],
+      ['string body', '"x"', 'body: must be a JSON object'],
+      ['invalid JSON', '{nope', 'body: invalid JSON'],
+      ['empty body', '', 'body: invalid JSON'],
+    ];
+    for (const [label, body, msg] of rows) {
+      const r = await app.req('POST', '/households', body);
+      assert.equal(r.status, 400, label);
+      assert.deepEqual(r.json, { error: msg }, label);
+    }
+    assert.equal(app.count('households'), 0);
+  }));
+
+test('POST /households: oversized body -> 413', () =>
+  withEnv(async (app) => {
+    const r = await app.req('POST', '/households', JSON.stringify({ name: 'x'.repeat(1048577) }));
+    assert.equal(r.status, 413);
+    assert.equal(app.count('households'), 0);
+  }));
+
+test('GET /households/:id unknown / undecodable -> 404; SQL-ish id is just not found', () =>
+  withEnv(async (app) => {
+    for (const id of ['nope', '%E0%A4%A', encodeURIComponent("' OR 1=1 --")]) {
+      const r = await app.req('GET', `/households/${id}`);
+      assert.equal(r.status, 404, id);
+      assert.deepEqual(r.json, { error: 'household not found' }, id);
+      const l = await app.req('GET', `/households/${id}/plans`);
+      assert.equal(l.status, 404, id);
+      assert.deepEqual(l.json, { error: 'household not found' }, id);
+    }
+  }));
+
+test('wrong methods -> 405 with Allow', () =>
+  withEnv(async (app) => {
+    const h = await app.mkHousehold();
+    const cases = [
+      ['GET', '/households', 'POST'], ['PUT', '/households', 'POST'], ['DELETE', '/households', 'POST'],
+      ['POST', `/households/${h.id}`, 'GET'], ['DELETE', `/households/${h.id}`, 'GET'],
+      ['POST', `/households/${h.id}/plans`, 'GET'], ['PUT', `/households/${h.id}/plans`, 'GET'],
+    ];
+    for (const [m, p, allow] of cases) {
+      const r = await app.req(m, p, m === 'POST' ? {} : undefined);
+      assert.equal(r.status, 405, `${m} ${p}`);
+      assert.equal(r.headers.allow, allow, `${m} ${p}`);
+    }
+  }));
+
+test('POST /plans with householdId: 201 carries it, GET returns identical body, list contains it', () =>
+  withEnv(async (app) => {
+    const h = await app.mkHousehold();
+    const p = await app.mkPlan({ householdId: h.id });
+    assert.equal(p.status, 201);
+    assert.equal(p.json.householdId, h.id);
+    const g = await app.req('GET', `/plans/${p.json.id}`);
+    assert.equal(g.status, 200);
+    assert.equal(g.text, p.text, 'POST and GET byte-identical');
+    assert.deepEqual((await app.req('GET', `/households/${h.id}/plans`)).json, [{ id: p.json.id, weekStart: '2025-01-06' }]);
+  }));
+
+test('POST /plans without householdId or with null: householdId is null in POST and GET', () =>
+  withEnv(async (app) => {
+    for (const extra of [{}, { householdId: null }]) {
+      const p = await app.mkPlan(extra);
+      assert.equal(p.status, 201);
+      assert.equal(p.json.householdId, null);
+      assert.ok('householdId' in p.json);
+      assert.deepEqual((await app.req('GET', `/plans/${p.json.id}`)).json, p.json);
+    }
+    assert.equal(app.db.prepare('SELECT COUNT(*) c FROM plans WHERE household_id IS NULL').get().c, 2);
+  }));
+
+test('POST /plans: unknown or empty householdId -> 404, Mealie untouched, no plan stored', () =>
+  withEnv(async (app) => {
+    for (const id of ['00000000-0000-0000-0000-000000000000', '', "x' OR '1'='1"]) {
+      const r = await app.mkPlan({ householdId: id });
+      assert.equal(r.status, 404, JSON.stringify(id));
+      assert.deepEqual(r.json, { error: 'household not found' });
