+'use strict';
+
+function positiveInt(v, fallback) {
+  if (typeof v !== 'string' || !/^\d+$/.test(v.trim())) return fallback;
+  const n = Number(v.trim());
+  return Number.isSafeInteger(n) && n > 0 ? n : fallback;
+}
+
+// loadConfig(env) -> {port, mealieUrl|null, databasePath, mealieTimeoutMs, concurrency}
+function loadConfig(env = process.env) {
+  const port = env.PORT === undefined || env.PORT === '' ? 3000 : Number(env.PORT);
+  if (!Number.isInteger(port) || port < 0 || port > 65535) throw new Error('PORT must be an integer from 0 to 65535');
+  const url = typeof env.MEALIE_URL === 'string' ? env.MEALIE_URL.trim() : '';
+  return {
+    port,
+    mealieUrl: url === '' ? null : url.replace(/\/+$/, ''),
+    databasePath: env.DATABASE_PATH ? env.DATABASE_PATH : './planner.db',
+    mealieTimeoutMs: positiveInt(env.MEALIE_TIMEOUT_MS, 10000),
+    concurrency: 4,
+  };
+}
+
+module.exports = { loadConfig };
