+'use strict';
+
+const path = require('node:path');
+const { loadConfig } = require('./config');
+const { open } = require('./db');
+const { migrate } = require('./migrations');
+const { createMealie } = require('./mealie');
+const { createServer } = require('./server');
+
+function main() {
+  let config;
+  let db;
+  try {
+    config = loadConfig(process.env);
+    db = open(config.databasePath);
+    migrate(db, path.join(__dirname, '..', 'migrations'));
+  } catch (err) {
+    console.error(`startup failed: ${err.message}`);
+    if (db) db.close();
+    process.exit(1);
+  }
+
+  const mealie = createMealie({ baseUrl: config.mealieUrl || '', timeoutMs: config.mealieTimeoutMs });
+  const server = createServer({ db, mealie });
+
+  server.on('error', (err) => {
+    console.error(`server error: ${err.message}`);
+    db.close();
+    process.exit(1);
+  });
+  server.listen(config.port, () => {
+    console.error(
+      `listening on port ${server.address().port}; sqlite driver ${db.driverName}; ` +
+      `MEALIE_URL ${config.mealieUrl ? 'set' : 'not set'}`
+    );
+  });
+
+  let stopping = false;
+  function stop() {
+    if (stopping) return;
+    stopping = true;
+    server.close(() => {
+      db.close();
+      process.exit(0);
+    });
+    if (typeof server.closeAllConnections === 'function') server.closeAllConnections();
+  }
+  process.on('SIGINT', stop);
+  process.on('SIGTERM', stop);
+}
+
+main();
