new file mode 100644
index 0000000..47ee4d6
--- /dev/null
+++ b/src/pool.js
@@ -0,0 +1,28 @@
+'use strict';
+
+// Runs fn(item, index) over items with at most `limit` in flight. Results keep
+// input order. Rejects with the first error and starts no new work afterwards.
+function mapLimit(items, limit, fn) {
+  const list = Array.from(items);
+  const results = new Array(list.length);
+  const workers = Math.max(1, Math.min(Math.floor(limit) || 1, list.length));
+  let next = 0;
+  let failed = false;
+
+  async function worker() {
+    while (!failed && next < list.length) {
+      const i = next++;
+      try {
+        results[i] = await fn(list[i], i);
+      } catch (err) {
+        failed = true;
+        throw err;
+      }
+    }
+  }
+
+  if (list.length === 0) return Promise.resolve(results);
+  return Promise.all(Array.from({ length: workers }, worker)).then(() => results);
+}
+
+module.exports = { mapLimit };
