+'use strict';
+
+const http = require('node:http');
+const crypto = require('node:crypto');
+const { HttpError, MealieError } = require('./errors');
+const { validatePlanRequest, selectEligible, buildPlan, foodLabelIndex, filterByDiet } = require('./planner');
+const { buildShoppingList, groupItemsByLabel } = require('./shopping');
+const { mapLimit } = require('./pool');
+
+const BODY_LIMIT = 102400;
+const CONCURRENCY = 4;
+
+function send(res, status, payload) {
+  const text = JSON.stringify(payload);
+  res.writeHead(status, {
+    'content-type': 'application/json; charset=utf-8',
+    'content-length': Buffer.byteLength(text),
+  });
+  res.end(text);
+}
+
+// Reads the body, counting bytes; stops reading once the limit is exceeded.
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    const declared = Number(req.headers['content-length']);
+    if (Number.isFinite(declared) && declared > BODY_LIMIT) {
+      reject(new HttpError(413, 'request body too large'));
+      return;
+    }
+    const chunks = [];
+    let size = 0;
+    let done = false;
+    function finish(err, value) {
+      if (done) return;
+      done = true;
+      req.removeListener('data', onData);
+      req.removeListener('end', onEnd);
+      req.removeListener('error', onError);
+      if (err) {
+        req.on('error', () => {});
+        req.pause();
+        reject(err);
+      } else {
+        resolve(value);
+      }
+    }
+    function onData(chunk) {
+      size += chunk.length;
+      if (size > BODY_LIMIT) finish(new HttpError(413, 'request body too large'));
+      else chunks.push(chunk);
+    }
+    function onEnd() { finish(null, Buffer.concat(chunks)); }
+    function onError() { finish(new HttpError(400, 'could not read request body')); }
+    req.on('data', onData);
+    req.on('end', onEnd);
+    req.on('error', onError);
+  });
+}
+
+function parseJson(buf) {
+  try {
+    return JSON.parse(buf.toString('utf8'));
+  } catch (_) {
+    throw new HttpError(400, 'request body must be valid JSON');
+  }
+}
+
+// Returns {name, id} or null. :id is one non-empty segment, decoded once.
+function route(pathname) {
+  if (pathname === '/health') return { name: 'health' };
+  if (pathname === '/plans') return { name: 'plans' };
+  const m = /^\/plans\/([^/]+)(\/shopping-list)?$/.exec(pathname);
+  if (!m) return null;
+  let id;
+  try {
+    id = decodeURIComponent(m[1]);
+  } catch (_) {
+    return null;
+  }
+  return { name: m[2] ? 'shopping' : 'plan', id };
+}
+
+function createServer({ db, mealie, hooks = {}, logger = null } = {}) {
+  const log = logger || ((msg) => console.error(msg));
+
+  function loadPlan(id) {
+    const plan = db.get('SELECT id, week_start FROM plans WHERE id = ?', [id]);
+    if (!plan) return null;
+    const rows = db.all(
+      'SELECT day_index, slot_index, date, slot, recipe_slug, recipe_name FROM plan_meals ' +
+      'WHERE plan_id = ? ORDER BY day_index, slot_index',
+      [id]
+    );
+    const days = [];
+    for (const r of rows) {
+      if (!days[r.day_index]) days[r.day_index] = { date: r.date, meals: [] };
+      days[r.day_index].meals.push({ slot: r.slot, recipeSlug: r.recipe_slug, recipeName: r.recipe_name });
+    }
+    return { id: plan.id, weekStart: plan.week_start, days: days.filter(Boolean) };
+  }
+
+  async function createPlan(req) {
+    const input = validatePlanRequest(parseJson(await readBody(req)));
+    const { rules } = input;
+
+    const recipes = await mealie.listRecipes();
+    let eligible = selectEligible(recipes, rules);
+    if (rules.diet.length > 0 && eligible.length > 0) {
+      const foods = await mealie.listFoods();
+      const index = foodLabelIndex(foods);
+      const details = await mapLimit(eligible, CONCURRENCY, (r) => mealie.getRecipe(r.slug));
+      const bySlug = new Map(eligible.map((r, i) => [r.slug, details[i]]));
+      eligible = filterByDiet(eligible, bySlug, index, rules.diet);
+    }
+    if (eligible.length === 0) throw new HttpError(409, 'no eligible recipe');
+
+    const plan = buildPlan({
+      id: crypto.randomUUID(),
+      weekStart: input.weekStart,
+      days: input.days,
+      mealsPerDay: rules.mealsPerDay,
+      eligible,
+    });
+
+    db.transaction(() => {
+      db.run(
+        'INSERT INTO plans (id, week_start, days, meals_per_day, rules_json, created_at) VALUES (?, ?, ?, ?, ?, ?)',
+        [plan.id, plan.weekStart, input.days, rules.mealsPerDay, JSON.stringify(rules), new Date().toISOString()]
+      );
+      let n = 0;
+      plan.days.forEach((day, di) => {
+        day.meals.forEach((meal, si) => {
+          if (hooks && typeof hooks.beforeInsertMeal === 'function') hooks.beforeInsertMeal(n);
+          n += 1;
+          db.run(
+            'INSERT INTO plan_meals (plan_id, day_index, slot_index, date, slot, recipe_slug, recipe_name) ' +
+            'VALUES (?, ?, ?, ?, ?, ?, ?)',
+            [plan.id, di, si, day.date, meal.slot, meal.recipeSlug, meal.recipeName]
+          );
+        });
+      });
+    });
+    return plan;
+  }
+
+  async function shoppingList(id, query) {
+    const meals = db.all('SELECT recipe_slug AS slug FROM plan_meals WHERE plan_id = ? ORDER BY day_index, slot_index', [id]);
+    const groupBy = query.getAll('groupBy');
+    if (groupBy.length > 0 && !(groupBy.length === 1 && groupBy[0] === 'label')) {
+      throw new HttpError(400, 'groupBy must be "label"');
+    }
+    const slugs = Array.from(new Set(meals.map((m) => m.slug)));
+    const details = await mapLimit(slugs, CONCURRENCY, (s) => mealie.getRecipe(s));
+    const bySlug = new Map(slugs.map((s, i) => [s, details[i]]));
+    const { items, notes } = buildShoppingList(meals, bySlug);
+    if (groupBy.length === 0) return { planId: id, items, notes };
+    const index = foodLabelIndex(await mealie.listFoods());
+    return { planId: id, groups: groupItemsByLabel(items, index), notes };
+  }
+
+  async function handle(req, res) {
+    let url;
+    try {
+      url = new URL(req.url, 'http://x');
+    } catch (_) {
+      throw new HttpError(404, 'not found');
+    }
+    const r = route(url.pathname);
+    if (!r) throw new HttpError(404, 'not found');
+    const allowed = r.name === 'plans' ? 'POST' : 'GET';
+    if (req.method !== allowed) {
+      res.setHeader('allow', allowed);
+      throw new HttpError(405, 'method not allowed');
+    }
+
+    if (r.name === 'health') return send(res, 200, { ok: true });
+    if (r.name === 'plans') return send(res, 201, await createPlan(req));
+
+    const plan = loadPlan(r.id);
+    if (!plan) throw new HttpError(404, 'plan not found');
+    if (r.name === 'plan') return send(res, 200, plan);
+    return send(res, 200, await shoppingList(r.id, url.searchParams));
+  }
+
+  return http.createServer((req, res) => {
+    handle(req, res).catch((err) => {
+      if (res.headersSent) {
+        res.destroy();
+        return;
+      }
+      if (err instanceof HttpError) {
+        if (err.status === 413) res.setHeader('connection', 'close');
+        send(res, err.status, { error: err.message });
+      } else if (err instanceof MealieError) {
+        log(`mealie failure: ${err.message}`);
+        send(res, 502, { error: err.message });
+      } else {
+        log(`internal error: ${err && err.stack ? err.stack : err}`);
+        send(res, 500, { error: 'internal error' });
+      }
+    });
+  });
+}
+
+module.exports = { createServer };
