+'use strict';
+// End-to-end HTTP tests: real server on an ephemeral port, in-process fake
+// Mealie (or scripted Mealie), :memory: or temp-file SQLite. Offline.
+const test = require('node:test');
+const assert = require('node:assert');
+const path = require('node:path');
+const {
+  startFakeMealie, startScripted, closedPort, createServer, openMigratedDb,
+  makeTempDir, removeDir, request,
+} = require('./helpers');
+const { createMealie } = require('../src/mealie');
+
+const WEEK = '2024-03-04';
+const quiet = () => {};
+
+// Builds an app over the given Mealie base URL. The Mealie client's fetch is
+// wrapped so every outgoing request path is recorded in `log`.
+async function makeApp({ baseUrl, db = openMigratedDb(), hooks, timeoutMs } = {}) {
+  const log = [];
+  const fetchLogged = (url, init) => {
+    log.push(new URL(url).pathname);
+    return fetch(url, init);
+  };
+  const mealie = createMealie({ baseUrl, fetch: fetchLogged, timeoutMs });
+  const app = await createServer({ db, mealie, hooks, logger: quiet });
+  return { app, db, log, url: app.url, close: () => app.close() };
+}
+
+async function withFake(fn, opts = {}) {
+  const fake = await startFakeMealie();
+  const ctx = await makeApp({ baseUrl: fake.url, ...opts });
+  try {
+    await fn(ctx);
+  } finally {
+    await ctx.close();
+    await fake.close();
+  }
+}
+
+const count = (db, table) => db.get(`SELECT COUNT(*) AS n FROM ${table}`).n;
+const post = (url, body) => request(`${url}/plans`, { method: 'POST', body });
+const plan = (rules, days = 7) => ({ weekStart: WEEK, days, rules });
+const slugsOf = (p) => p.days.flatMap((d) => d.meals.map((m) => m.recipeSlug));
+const foodsCalls = (log) => log.filter((p) => p === '/api/foods').length;
+const detailCalls = (log) => log.filter((p) => /^\/api\/recipes\/.+/.test(p));
+
+function assertErrorBody(res, status) {
+  assert.strictEqual(res.status, status, res.text);
+  assert.match(res.headers.get('content-type'), /^application\/json/);
+  assert.deepStrictEqual(Object.keys(res.json), ['error']);
+  assert.strictEqual(typeof res.json.error, 'string');
+  assert.ok(res.json.error.length > 0);
+}
+
+// ---------------------------------------------------------------- H
+
+test('H1 GET /health', async () => {
+  await withFake(async ({ url, log }) => {
+    const res = await request(`${url}/health`);
+    assert.strictEqual(res.status, 200);
+    assert.match(res.headers.get('content-type'), /^application\/json/);
+    assert.deepStrictEqual(res.json, { ok: true });
+    assert.deepStrictEqual(log, []);
+  });
