+
+test('H2 POST /plans validation table returns 400 with a single error key', async () => {
+  await withFake(async ({ url, db, log }) => {
+    const bodies = [
+      '{not json',
+      '[]',
+      'null',
+      '"x"',
+      {},
+      { weekStart: '2024-03-05' },
+      { weekStart: '2024-02-30' },
+      { weekStart: 'monday' },
+      { weekStart: WEEK, days: 0 },
+      { weekStart: WEEK, days: 15 },
+      { weekStart: WEEK, days: 1.5 },
+      { weekStart: WEEK, rules: [] },
+      { weekStart: WEEK, rules: { mealsPerDay: 4 } },
+      { weekStart: WEEK, rules: { includeTags: 'vegan' } },
+      { weekStart: WEEK, rules: { excludeTags: [1] } },
+      { weekStart: WEEK, rules: { maxTotalTimeMinutes: -1 } },
