+    assertErrorBody(await request(`${url}/nope`), 404);
+    assertErrorBody(await request(`${url}/plans/`), 404);
+    assertErrorBody(await request(`${url}/health/`), 404);
+    assertErrorBody(await request(`${url}/plans/%E0%A4%A`), 404);
+    assertErrorBody(await request(`${url}/plans/a/b/shopping-list`), 404);
+  });
+});
+
+test('H3 POST then GET plan round trip, including after a restart on the same DB file', async () => {
+  const dir = makeTempDir();
+  const file = path.join(dir, 'planner.db');
+  const fake = await startFakeMealie();
