+    const created = await post(ctx.url, plan({ includeTags: ['vegan'], mealsPerDay: 2 }, 2));
+    assert.strictEqual(created.status, 201, created.text);
+    assert.match(created.json.id, /^[0-9a-f-]{36}$/);
