+    assert.strictEqual(created.json.days.length, 2);
+    assert.deepStrictEqual(created.json.days.map((d) => d.date), ['2024-03-04', '2024-03-05']);
+    assert.deepStrictEqual(created.json.days[0].meals.map((m) => m.slot), ['lunch', 'dinner']);
+    const got = await request(`${ctx.url}/plans/${created.json.id}`);
