+    // restart: new db handle, new server, no Mealie needed for GET /plans/:id
+    db = openMigratedDb(file);
+    ctx = await makeApp({ baseUrl: '', db });
+    const again = await request(`${ctx.url}/plans/${created.json.id}`);
+    assert.strictEqual(again.status, 200);
+    assert.deepStrictEqual(again.json, created.json);
+    assertErrorBody(await request(`${ctx.url}/plans/unknown-id`), 404);
+    assert.strictEqual((await request(`${ctx.url}/plans/unknown-id`)).json.error, 'plan not found');
+    assert.deepStrictEqual(ctx.log, []);
+    await ctx.close();
+    db.close();
+  } finally {
+    await fake.close();
+    removeDir(dir);
