+// Scripted Mealie: recipe summaries, details and foods under test control.
+function scriptedMealie({ recipes, foods }) {
+  return startScripted((req, res) => {
+    const url = new URL(req.url, 'http://x');
+    const send = (body) => {
+      res.writeHead(200, { 'content-type': 'application/json' });
+      res.end(JSON.stringify(body));
+    };
+    if (url.pathname === '/api/recipes') {
+      return send({ page: 1, per_page: 50, total: recipes.length, total_pages: 1,
+        items: recipes.map((r) => ({ id: r.slug, slug: r.slug, name: r.name, tags: [], totalTime: null })) });
+    }
+    if (url.pathname === '/api/foods') {
+      return send({ page: 1, per_page: 50, total: foods.length, total_pages: 1,
+        items: foods.map((f, i) => ({ id: `f${i}`, name: f.name, label: f.label === null ? null : { name: f.label } })) });
+    }
+    const m = /^\/api\/recipes\/(.+)$/.exec(url.pathname);
+    const r = m && recipes.find((x) => x.slug === decodeURIComponent(m[1]));
+    if (r) return send({ slug: r.slug, recipeIngredient: r.ingredients.map((n) => ({ quantity: 1, unit: null, food: { name: n }, note: '' })) });
+    res.writeHead(404, { 'content-type': 'application/json' });
+    res.end('{}');
+  });
+}
