+      { name: 'gamma', label: 'Banana' },
+      // delta not listed
+    ],
+  });
+  const ctx = await makeApp({ baseUrl: mealie.url });
+  try {
+    const created = await post(ctx.url, plan({}, 1));
+    assert.strictEqual(created.status, 201, created.text);
+    const res = await grouped(ctx.url, created.json.id);
+    assert.strictEqual(res.status, 200, res.text);
+    assert.deepStrictEqual(res.json.groups, [
+      { label: 'Banana', items: [{ food: 'gamma', quantity: 1, unit: null }] },
+      { label: 'Zucchini', items: [{ food: 'zed', quantity: 1, unit: null }] },
+      { label: 'apple', items: [{ food: 'beta', quantity: 1, unit: null }] },
+      { label: 'Other', items: [
+        { food: 'alpha', quantity: 1, unit: null },
+        { food: 'delta', quantity: 1, unit: null },
+      ] },
+    ]);
+  } finally {
