+  assert.deepStrictEqual(validatePlanRequest({ weekStart: '2024-03-04' }).rules.diet, []);
+});
+
+test('D1 each diet value and [] are accepted', () => {
+  for (const d of ['vegetarian', 'vegan', 'gluten-free']) {
+    assert.deepStrictEqual(validatePlanRequest(req({ diet: [d] })).rules.diet, [d]);
+  }
+  assert.deepStrictEqual(validatePlanRequest(req({ diet: [] })).rules.diet, []);
+});
+
+test('D1 duplicates removed, canonical order', () => {
+  const r = validatePlanRequest(req({ diet: ['gluten-free', 'vegan', 'gluten-free', 'vegetarian', 'vegan'] }));
+  assert.deepStrictEqual(r.rules.diet, ['vegetarian', 'vegan', 'gluten-free']);
+});
+
+test('D1 invalid diet values are 400', () => {
+  for (const bad of ['vegan', null, 5, {}, ['keto'], ['Vegan'], ['vegan', 1], [null], [['vegan']], ['']]) {
+    assert.throws(() => validatePlanRequest(req({ diet: bad })), (e) => e instanceof HttpError && e.status === 400, JSON.stringify(bad));
+  }
+});
+
+test('D1 earlier rule failures win over diet', () => {
+  assert.throws(
+    () => validatePlanRequest(req({ maxTotalTimeMinutes: -1, diet: ['keto'] })),
+    (e) => e.status === 400 && /maxTotalTimeMinutes/.test(e.message),
+  );
+});
+
+test('D2 banned sets and union', () => {
+  assert.deepStrictEqual([...bannedLabels(['vegetarian'])].sort(), ['Fish', 'Meat']);
+  assert.deepStrictEqual([...bannedLabels(['vegan'])].sort(), ['Dairy', 'Egg', 'Fish', 'Meat']);
+  assert.deepStrictEqual([...bannedLabels(['gluten-free'])], ['Gluten']);
+  assert.deepStrictEqual([...bannedLabels(['vegetarian', 'gluten-free'])].sort(), ['Fish', 'Gluten', 'Meat']);
