+  { id: '4', name: 'milk', label: 'Dairy' },
+  { id: '5', name: 'Milk', label: 'Other' },
+  { id: '6', name: '   ', label: 'Meat' },
+  { id: '7', name: 'steak', label: 'meat' },
+];
+const index = foodLabelIndex(foods);
+const ing = (name) => ({ food: name === undefined ? null : { name } });
+
+test('D3 food names match case-insensitively and trimmed', () => {
+  assert.deepStrictEqual([...recipeLabels([ing('CHICKEN breast')], index)], ['Meat']);
+  assert.deepStrictEqual([...recipeLabels([ing('  flour')], index)], ['Gluten']);
+});
+
+test('D3 duplicate name: first food wins; blank names skipped', () => {
+  assert.strictEqual(index.get('milk'), 'Dairy');
+  assert.strictEqual(index.has(''), false);
+});
+
+test('D3 unlisted food, null label, null food, blank or non-string name give no label', () => {
+  const ings = [ing('unicorn'), ing('rice'), ing(undefined), ing('  '), { food: { name: 5 } }, { food: 'x' }, {}];
+  assert.strictEqual(recipeLabels(ings, index).size, 0);
+});
+
+test('D3 banned labels match exactly: label "meat" does not ban, "Meat" does', () => {
+  const recipes = [{ slug: 'steak' }, { slug: 'chicken' }];
+  const details = new Map([
+    ['steak', { recipeIngredient: [ing('steak')] }],
+    ['chicken', { recipeIngredient: [ing('chicken breast')] }],
+  ]);
+  const out = filterByDiet(recipes, details, index, ['vegetarian']);
+  assert.deepStrictEqual(out.map((r) => r.slug), ['steak']);
