+test('D3 unlisted food is never banned; recipe without ingredients is kept', () => {
+  const recipes = [{ slug: 'a' }, { slug: 'b' }, { slug: 'c' }];
+  const details = new Map([
+    ['a', { recipeIngredient: [ing('unicorn')] }],
+    ['b', { recipeIngredient: [] }],
+    ['c', { recipeIngredient: [ing('FLOUR'), ing('rice')] }],
+  ]);
+  assert.deepStrictEqual(filterByDiet(recipes, details, index, ['vegan']).map((r) => r.slug), ['a', 'b', 'c']);
+  assert.deepStrictEqual(filterByDiet(recipes, details, index, ['gluten-free']).map((r) => r.slug), ['a', 'b']);
+});
+
+test('D3 empty diet keeps everything without needing details', () => {
+  const recipes = [{ slug: 'a' }];
+  assert.deepStrictEqual(filterByDiet(recipes, new Map(), index, []), recipes);
+});
+
+test('D3 __proto__ food names are harmless', () => {
+  const idx = foodLabelIndex([{ name: '__proto__', label: 'Meat' }]);
+  assert.strictEqual(recipeLabels([ing('__proto__')], idx).has('Meat'), true);
+  assert.strictEqual(recipeLabels([ing('constructor')], idx).size, 0);
+});
+
+test('D4 non-object ingredient is a MealieError', () => {
+  for (const bad of [null, 'milk', 3, []]) {
+    assert.throws(() => recipeLabels([bad], index), (e) => e instanceof MealieError);
+  }
+});
+
+test('D4 missing detail is a MealieError', () => {
+  assert.throws(() => filterByDiet([{ slug: 'a' }], new Map(), index, ['vegan']), (e) => e instanceof MealieError);
+});
