+'use strict';
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const path = require('node:path');
+const crypto = require('node:crypto');
+const db = require('../src/db');
+const { migrate } = require('../src/migrations');
+const { ROOT, makeTempDir, removeDir } = require('./helpers');
+
+const MIGRATIONS = path.join(ROOT, 'migrations');
+const SHA_001 = '79ae67a11494768723c07d167e474dc6964f0a059094c58f0d5123117e1f3dcc';
+
+function nodeSqliteLoadable() {
+  if (!db.nodeSqliteSupported()) return false;
+  try { require('node:sqlite'); return true; } catch (_) { return false; }
+}
+
+// Each driver is exercised explicitly via opts.driver. The default driver
+// (honouring MEALIE_PLANNER_SQLITE) is covered as well.
+const drivers = [{ label: 'default driver', opts: {} }];
+drivers.push({
+  label: 'node:sqlite',
+  opts: { driver: 'node' },
+  skip: nodeSqliteLoadable() ? false : 'node:sqlite needs Node >= 22.13 and a loadable module',
+});
+try {
+  require('better-sqlite3');
+  drivers.push({ label: 'better-sqlite3', opts: { driver: 'better' } });
+} catch (_) {
+  drivers.push({ label: 'better-sqlite3', opts: {}, skip: 'better-sqlite3 not installed' });
+}
+
+function openWith(file, opts) {
+  // opts.driver === 'better' means "not forced to node" (primary driver).
+  const prev = process.env.MEALIE_PLANNER_SQLITE;
+  if (opts.driver === 'better') delete process.env.MEALIE_PLANNER_SQLITE;
+  try {
+    return db.open(file, opts.driver === 'better' ? {} : opts);
+  } finally {
+    if (prev === undefined) delete process.env.MEALIE_PLANNER_SQLITE;
+    else process.env.MEALIE_PLANNER_SQLITE = prev;
+  }
+}
+
+function only001Dir(parent) {
+  const dir = path.join(parent, 'only001');
+  fs.mkdirSync(dir);
+  fs.copyFileSync(path.join(MIGRATIONS, '001_init.sql'), path.join(dir, '001_init.sql'));
+  return dir;
+}
+
+function insertOldPlan(d) {
+  d.run(
+    'INSERT INTO plans (id, week_start, days, meals_per_day, rules_json, created_at) VALUES (?, ?, ?, ?, ?, ?)',
+    ['old-plan', '2024-01-01', 1, 1, '{}', '2024-01-01T00:00:00.000Z']
+  );
+  d.run(
+    'INSERT INTO plan_meals (plan_id, day_index, slot_index, date, slot, recipe_slug, recipe_name) VALUES (?, ?, ?, ?, ?, ?, ?)',
+    ['old-plan', 0, 0, '2024-01-01', 'dinner', 'soup', 'Soup']
+  );
+}
+
+for (const drv of drivers) {
+  const opts = { skip: drv.skip };
+
+  test(`AC upgrade from 001-only DB keeps data and adds households (${drv.label})`, opts, function () {
+    const dir = makeTempDir();
+    const file = path.join(dir, 'up.db');
+    try {
+      let d = openWith(file, drv.opts);
+      migrate(d, only001Dir(dir));
+      insertOldPlan(d);
+      assert.deepEqual(d.all('SELECT name FROM schema_migrations ORDER BY name').map((r) => r.name), ['001_init.sql']);
+      d.close();
+
+      d = openWith(file, drv.opts);
+      migrate(d, MIGRATIONS);
+
+      assert.deepEqual(
+        d.all('SELECT name FROM schema_migrations ORDER BY name').map((r) => r.name),
+        ['001_init.sql', '002_households.sql']
+      );
+
+      const old = d.get('SELECT id, week_start, household_id FROM plans WHERE id = ?', ['old-plan']);
+      assert.deepEqual(old, { id: 'old-plan', week_start: '2024-01-01', household_id: null });
+      assert.equal(d.all('SELECT * FROM plan_meals WHERE plan_id = ?', ['old-plan']).length, 1);
+
+      const fks = d.all('PRAGMA foreign_key_list(plans)');
+      assert.ok(
+        fks.some((f) => f.table === 'households' && f.from === 'household_id' && f.to === 'id'),
+        JSON.stringify(fks)
+      );
+      const idx = d.all('PRAGMA index_info(idx_plans_household)').map((r) => r.name);
+      assert.deepEqual(idx, ['household_id', 'week_start', 'id']);
+
+      // A household and a plan referencing it can be created and read back.
+      d.run('INSERT INTO households (id, name, created_at) VALUES (?, ?, ?)', ['h1', 'Home', '2024-02-01T00:00:00.000Z']);
+      d.run(
+        'INSERT INTO plans (id, week_start, days, meals_per_day, rules_json, created_at, household_id) VALUES (?, ?, ?, ?, ?, ?, ?)',
+        ['new-plan', '2024-02-05', 1, 1, '{}', '2024-02-01T00:00:00.000Z', 'h1']
+      );
+      assert.deepEqual(
+        d.all('SELECT p.id FROM plans p JOIN households h ON h.id = p.household_id WHERE h.id = ?', ['h1']),
+        [{ id: 'new-plan' }]
+      );
+      // The old plan is not attributed to any household.
+      assert.deepEqual(d.all('SELECT id FROM plans WHERE household_id IS NULL'), [{ id: 'old-plan' }]);
+      d.close();
+    } finally {
+      removeDir(dir);
+    }
+  });
+
+  test(`AC foreign key enforced for bogus household_id (${drv.label})`, opts, function () {
+    const d = openWith(':memory:', drv.opts);
+    try {
+      migrate(d, MIGRATIONS);
+      assert.throws(function () {
+        d.run(
+          'INSERT INTO plans (id, week_start, days, meals_per_day, rules_json, created_at, household_id) VALUES (?, ?, ?, ?, ?, ?, ?)',
+          ['bad', '2024-02-05', 1, 1, '{}', 'x', 'no-such-household']
+        );
+      }, /FOREIGN KEY/i);
+      assert.equal(d.get('SELECT COUNT(*) AS n FROM plans WHERE id = ?', ['bad']).n, 0);
+    } finally {
+      d.close();
+    }
+  });
+
+  test(`AC migrate twice is a no-op (${drv.label})`, opts, function () {
+    const d = openWith(':memory:', drv.opts);
+    try {
+      migrate(d, MIGRATIONS);
+      const before = d.all('SELECT name, applied_at, checksum FROM schema_migrations ORDER BY name');
+      assert.equal(before.length, 2);
+      migrate(d, MIGRATIONS);
+      const after = d.all('SELECT name, applied_at, checksum FROM schema_migrations ORDER BY name');
+      assert.deepEqual(after, before);
+    } finally {
+      d.close();
+    }
+  });
+}
+
+test('AC 001_init.sql is unchanged (sha256 guard)', function () {
+  const bytes = fs.readFileSync(path.join(MIGRATIONS, '001_init.sql'));
+  assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'), SHA_001);
+});
+
+test('AC a failing migration rolls back and leaves the DB at 001', function () {
+  const dir = makeTempDir();
+  try {
+    const mdir = only001Dir(dir);
+    const d = db.open(':memory:');
+    migrate(d, mdir);
+    fs.writeFileSync(
+      path.join(mdir, '002_households.sql'),
+      'CREATE TABLE households (id TEXT PRIMARY KEY);\nTHIS IS NOT SQL;\n'
+    );
+    assert.throws(function () { migrate(d, mdir); });
+    assert.equal(d.get("SELECT COUNT(*) AS n FROM sqlite_master WHERE name = 'households'").n, 0);
+    assert.deepEqual(d.all('SELECT name FROM schema_migrations').map((r) => r.name), ['001_init.sql']);
+    d.close();
+  } finally {
+    removeDir(dir);
+  }
+});
+
+test('AC a modified applied migration is refused', function () {
+  const dir = makeTempDir();
+  try {
+    const mdir = path.join(dir, 'm');
+    fs.mkdirSync(mdir);
+    fs.copyFileSync(path.join(MIGRATIONS, '001_init.sql'), path.join(mdir, '001_init.sql'));
+    const d = db.open(':memory:');
+    migrate(d, mdir);
+    fs.appendFileSync(path.join(mdir, '001_init.sql'), '\n-- edited\n');
+    assert.throws(function () { migrate(d, mdir); }, /modified after being applied/);
+    d.close();
+  } finally {
+    removeDir(dir);
+  }
+});

