+'use strict';
+const http = require('http');
+const { HttpError, createPlan, loadPlan, shoppingList } = require('./planner');
+const { MealieError } = require('./mealie');
+
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    const chunks = [];
+    req.on('data', (c) => chunks.push(c));
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+function createApp({ db, mealie }) {
+  async function route(req) {
+    const path = new URL(req.url, 'http://x').pathname.replace(/\/+$/, '') || '/';
+    if (path === '/health' && req.method === 'GET') return [200, { ok: true }];
+    if (path === '/plans' && req.method === 'POST') {
+      let body;
+      try {
+        body = JSON.parse(await readBody(req));
+      } catch (e) {
+        throw new HttpError(400, 'invalid JSON body');
+      }
+      return [201, await createPlan(db, mealie, body)];
+    }
+    let m = path.match(/^\/plans\/([^/]+)$/);
+    if (m && req.method === 'GET') {
+      const plan = loadPlan(db, decodeURIComponent(m[1]));
+      if (!plan) throw new HttpError(404, 'plan not found');
+      return [200, plan];
+    }
+    m = path.match(/^\/plans\/([^/]+)\/shopping-list$/);
+    if (m && req.method === 'GET') {
+      const list = shoppingList(db, decodeURIComponent(m[1]));
+      if (!list) throw new HttpError(404, 'plan not found');
+      return [200, list];
+    }
+    throw new HttpError(404, 'not found');
+  }
+
+  return http.createServer(async (req, res) => {
+    let status, body;
+    try {
+      [status, body] = await route(req);
+    } catch (e) {
+      if (e instanceof HttpError) [status, body] = [e.status, { error: e.message }];
+      else if (e instanceof MealieError) [status, body] = [502, { error: e.message }];
+      else {
+        console.error(e);
+        [status, body] = [500, { error: 'internal error' }];
+      }
+    }
+    res.writeHead(status, { 'content-type': 'application/json' });
+    res.end(JSON.stringify(body));
+  });
+}
+
+module.exports = { createApp };
diff --git a/src/db.js b/src/db.js
new file mode 100644
index 0000000..b2079da
--- /dev/null
+++ b/src/db.js
@@ -0,0 +1,30 @@
+'use strict';
+const fs = require('fs');
+const path = require('path');
+const Database = require('better-sqlite3');
+
+const MIGRATIONS_DIR = path.join(__dirname, '..', 'migrations');
+
+function migrate(db) {
+  db.exec('CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)');
+  const done = new Set(db.prepare('SELECT name FROM schema_migrations').all().map((r) => r.name));
+  const files = fs.readdirSync(MIGRATIONS_DIR).filter((f) => /^\d+_.+\.sql$/.test(f)).sort();
+  for (const file of files) {
+    if (done.has(file)) continue;
+    const sql = fs.readFileSync(path.join(MIGRATIONS_DIR, file), 'utf8');
+    db.transaction(() => {
+      db.exec(sql);
+      db.prepare('INSERT INTO schema_migrations (name, applied_at) VALUES (?, ?)').run(file, new Date().toISOString());
+    })();
+  }
+}
+
+function open(file) {
+  const db = new Database(file);
+  db.pragma('journal_mode = WAL');
+  db.pragma('foreign_keys = ON');
+  migrate(db);
+  return db;
+}
+
+module.exports = { open, migrate };
