@@ -0,0 +1,40 @@
+'use strict';
+
+class MealieError extends Error {}
+
+function createClient(baseUrl) {
+  const base = String(baseUrl || '').replace(/\/+$/, '');
+
+  async function get(p) {
+    let res;
+    try {
+      res = await fetch(base + p);
+    } catch (e) {
+      throw new MealieError(`Mealie unreachable: ${e.message}`);
+    }
+    if (!res.ok) throw new MealieError(`Mealie answered ${res.status} for ${p}`);
+    try {
+      return await res.json();
+    } catch (e) {
+      throw new MealieError(`Mealie sent invalid JSON for ${p}`);
+    }
+  }
+
+  // Pages may hold fewer items than asked for, so follow total_pages.
+  async function listRecipes() {
+    const all = new Map();
+    for (let page = 1; ; page++) {
+      const body = await get(`/api/recipes?page=${page}&perPage=100`);
+      const items = Array.isArray(body.items) ? body.items : [];
+      for (const r of items) all.set(r.slug, r);
+      if (!items.length || page >= (Number(body.total_pages) || 1)) break;
+    }
+    return [...all.values()];
+  }
+
+  const getRecipe = (slug) => get(`/api/recipes/${encodeURIComponent(slug)}`);
+
+  return { listRecipes, getRecipe };
+}
+
+module.exports = { createClient, MealieError };
diff --git a/src/planner.js b/src/planner.js
new file mode 100644
index 0000000..1ee1df9
--- /dev/null
+++ b/src/planner.js
@@ -0,0 +1,165 @@
+'use strict';
+const { randomUUID } = require('crypto');
+
+class HttpError extends Error {
+  constructor(status, message) {
+    super(message);
+    this.status = status;
+  }
+}
+
+const SLOTS = { 1: ['dinner'], 2: ['lunch', 'dinner'], 3: ['breakfast', 'lunch', 'dinner'] };
+
+function cmp(a, b) {
+  return a < b ? -1 : a > b ? 1 : 0;
+}
+
+function parseDate(s) {
+  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
+  const d = new Date(`${s}T00:00:00Z`);
+  return Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== s ? null : d;
+}
+
+function addDays(d, n) {
+  return new Date(d.getTime() + n * 86400000).toISOString().slice(0, 10);
+}
+
+// ISO 8601 duration to minutes; null when absent or malformed.
+function durationMinutes(s) {
+  if (typeof s !== 'string') return null;
+  const m = s.match(/^P(?:(\d+(?:\.\d+)?)D)?(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?$/);
+  if (!m || s === 'P' || s.endsWith('T')) return null;
+  const [d, h, mi, sec] = m.slice(1).map(Number);
+  return (d || 0) * 1440 + (h || 0) * 60 + (mi || 0) + (sec || 0) / 60;
+}
+
+function validate(body) {
+  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new HttpError(400, 'body must be a JSON object');
+  const start = parseDate(body.weekStart);
+  if (!start) throw new HttpError(400, 'weekStart must be a valid date (YYYY-MM-DD)');
+  if (start.getUTCDay() !== 1) throw new HttpError(400, 'weekStart must be a Monday');
+  const days = body.days === undefined ? 7 : body.days;
+  if (!Number.isInteger(days) || days < 1 || days > 14) throw new HttpError(400, 'days must be an integer from 1 to 14');
+  const rules = body.rules === undefined ? {} : body.rules;
+  if (!rules || typeof rules !== 'object' || Array.isArray(rules)) throw new HttpError(400, 'rules must be an object');
+  const mealsPerDay = rules.mealsPerDay === undefined ? 1 : rules.mealsPerDay;
+  if (!Number.isInteger(mealsPerDay) || mealsPerDay < 1 || mealsPerDay > 3) throw new HttpError(400, 'mealsPerDay must be an integer from 1 to 3');
+  const tags = (key) => {
+    const v = rules[key] === undefined ? [] : rules[key];
+    if (!Array.isArray(v) || v.some((t) => typeof t !== 'string')) throw new HttpError(400, `${key} must be an array of strings`);
+    return v;
+  };
+  const includeTags = tags('includeTags');
+  const excludeTags = tags('excludeTags');
+  const max = rules.maxTotalTimeMinutes === undefined ? null : rules.maxTotalTimeMinutes;
+  if (max !== null && (typeof max !== 'number' || !Number.isFinite(max) || max < 0)) throw new HttpError(400, 'maxTotalTimeMinutes must be a non-negative number or null');
+  return { weekStart: body.weekStart, start, days, mealsPerDay, includeTags, excludeTags, max };
+}
+
+function eligible(recipe, r) {
+  const slugs = new Set((recipe.tags || []).map((t) => t.slug));
+  if (!r.includeTags.every((t) => slugs.has(t))) return false;
+  if (r.excludeTags.some((t) => slugs.has(t))) return false;
+  if (r.max !== null) {
+    const m = durationMinutes(recipe.totalTime);
+    if (m === null || m > r.max) return false;
+  }
+  return true;
+}
+
+function loadPlan(db, id) {
+  const plan = db.prepare('SELECT * FROM plans WHERE id = ?').get(id);
+  if (!plan) return null;
+  const meals = db.prepare('SELECT * FROM plan_meals WHERE plan_id = ? ORDER BY position').all(id);
+  const days = [];
+  for (const m of meals) {
+    if (!days.length || days[days.length - 1].date !== m.date) days.push({ date: m.date, meals: [] });
+    days[days.length - 1].meals.push({ slot: m.slot, recipeSlug: m.recipe_slug, recipeName: m.recipe_name });
+  }
+  return { id: plan.id, weekStart: plan.week_start, days };
+}
+
+async function createPlan(db, mealie, body) {
+  const r = validate(body);
+  const pool = (await mealie.listRecipes()).filter((x) => eligible(x, r)).sort((a, b) => cmp(a.slug, b.slug));
+  if (!pool.length) throw new HttpError(409, 'no eligible recipes');
+
+  const slots = SLOTS[r.mealsPerDay];
+  const meals = [];
+  for (let d = 0; d < r.days; d++) {
+    slots.forEach((slot, s) => {
+      const recipe = pool[(d * slots.length + s) % pool.length];
+      meals.push({ date: addDays(r.start, d), slot, slug: recipe.slug, name: recipe.name });
+    });
+  }
+
+  const details = new Map();
+  for (const slug of new Set(meals.map((m) => m.slug))) details.set(slug, await mealie.getRecipe(slug));
+
+  const id = randomUUID();
+  db.transaction(() => {
+    db.prepare('INSERT INTO plans (id, week_start, day_count) VALUES (?, ?, ?)').run(id, r.weekStart, r.days);
+    const insMeal = db.prepare('INSERT INTO plan_meals (plan_id, position, date, slot, recipe_slug, recipe_name) VALUES (?, ?, ?, ?, ?, ?)');
+    meals.forEach((m, i) => insMeal.run(id, i, m.date, m.slot, m.slug, m.name));
+    const insIng = db.prepare('INSERT INTO plan_ingredients (plan_id, recipe_slug, position, quantity, unit_abbr, food, note) VALUES (?, ?, ?, ?, ?, ?, ?)');
+    for (const [slug, recipe] of details) {
+      (recipe.recipeIngredient || []).forEach((ing, i) => {
+        const unit = ing.unit && (ing.unit.abbreviation || ing.unit.name);
+        const food = ing.food && typeof ing.food.name === 'string' ? ing.food.name : null;
+        insIng.run(id, slug, i, typeof ing.quantity === 'number' ? ing.quantity : null, unit || null, food, ing.note || '');
+      });
+    }
+  })();
+  return loadPlan(db, id);
+}
+
+const MASS = { g: 1, kg: 1000 };
+const VOLUME = { ml: 1, l: 1000, tsp: 5, tbsp: 15, cup: 240 };
+const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
+
+function scaled(food, base, small, large) {
+  const q = round2(base);
+  return q < 1000 ? { food, quantity: q, unit: small } : { food, quantity: round2(base / 1000), unit: large };
+}
+
+function shoppingList(db, id) {
+  if (!db.prepare('SELECT 1 FROM plans WHERE id = ?').get(id)) return null;
+  // One row per planned meal and ingredient: a recipe planned twice counts twice.
+  const rows = db.prepare(`
+    SELECT i.quantity, i.unit_abbr, i.food, i.note
+    FROM plan_meals m JOIN plan_ingredients i ON i.plan_id = m.plan_id AND i.recipe_slug = m.recipe_slug
+    WHERE m.plan_id = ?`).all(id);
+
+  const groups = new Map();
+  const notes = new Set();
+  for (const row of rows) {
+    const food = row.food === null ? '' : row.food.trim().toLowerCase();
+    if (!food) {
+      const note = (row.note || '').trim();
+      if (note) notes.add(note);
+      continue;
+    }
+    const qty = row.quantity === null ? 1 : row.quantity;
+    const abbr = row.unit_abbr === null ? null : row.unit_abbr.trim();
+    const u = abbr ? abbr.toLowerCase() : null;
+    let kind, amount, unit = null;
+    if (u === null) { kind = 'count'; amount = qty; }
+    else if (u in MASS) { kind = 'mass'; amount = qty * MASS[u]; }
+    else if (u in VOLUME) { kind = 'volume'; amount = qty * VOLUME[u]; }
+    else { kind = `other:${u}`; amount = qty; unit = abbr; }
+    const key = `${food}\u0000${kind}`;
+    const g = groups.get(key) || { food, kind, unit, amount: 0 };
+    g.amount += amount;
+    groups.set(key, g);
+  }
+
+  const items = [...groups.values()].map((g) => {
+    if (g.kind === 'mass') return scaled(g.food, g.amount, 'g', 'kg');
+    if (g.kind === 'volume') return scaled(g.food, g.amount, 'ml', 'l');
+    return { food: g.food, quantity: round2(g.amount), unit: g.unit };
+  });
+  items.sort((a, b) => cmp(a.food, b.food) || (a.unit === b.unit ? 0 : a.unit === null ? -1 : b.unit === null ? 1 : cmp(a.unit, b.unit)));
+  return { planId: id, items, notes: [...notes].sort(cmp) };
+}
+
+module.exports = { HttpError, createPlan, loadPlan, shoppingList, durationMinutes };
diff --git a/test/api.test.js b/test/api.test.js
new file mode 100644
index 0000000..89cb695
--- /dev/null
+++ b/test/api.test.js
@@ -0,0 +1,239 @@
+'use strict';
+const test = require('node:test');
+const assert = require('node:assert');
+const fs = require('fs');
+const os = require('os');
+const path = require('path');
+const fakeMealie = require('../dev/fake-mealie/server');
+const sample = require('../dev/fake-mealie/sample.json');
+const { open } = require('../src/db');
+const { createClient } = require('../src/mealie');
+const { createApp } = require('../src/app');
+const { durationMinutes } = require('../src/planner');
+
+async function boot(data) {
+  const mealie = await fakeMealie.start({ data });
+  const db = open(':memory:');
+  const server = createApp({ db, mealie: createClient(mealie.url) });
+  await new Promise((r) => server.listen(0, '127.0.0.1', r));
+  const base = `http://127.0.0.1:${server.address().port}`;
+  const call = async (method, p, body) => {
+    const res = await fetch(base + p, { method, headers: { 'content-type': 'application/json' }, body: body === undefined ? undefined : JSON.stringify(body) });
+    return { status: res.status, body: await res.json() };
+  };
+  return {
+    call,
+    db,
+    close: async () => { server.close(); await mealie.close(); db.close(); },
+  };
+}
+
+const recipe = (slug, ingredients, extra = {}) => ({
+  id: slug, slug, name: slug.toUpperCase(), tags: [], totalTime: null, recipeIngredient: ingredients, ...extra,
+});
+const ing = (quantity, abbr, food, note = '') => ({
+  quantity, unit: abbr ? { name: abbr, abbreviation: abbr } : null, food: food ? { name: food } : null, note,
+});
+
+test('health', async () => {
+  const s = await boot(sample);
+  try {
+    assert.deepStrictEqual(await s.call('GET', '/health'), { status: 200, body: { ok: true } });
+  } finally { await s.close(); }
+});
+
+test('plan from sample data: slug order, wrap-around, read back', async () => {
+  const s = await boot(sample);
+  try {
+    const res = await s.call('POST', '/plans', { weekStart: '2026-10-26' });
+    assert.strictEqual(res.status, 201);
+    const slugs = sample.recipes.map((r) => r.slug).sort();
