+++ b/src/app.js
@@ -0,0 +1,93 @@
+'use strict';
+const http = require('http');
+const { randomUUID } = require('crypto');
+const { validateRequest, buildSchedule, ValidationError, NoRecipesError } = require('./planner');
+const { buildShoppingList } = require('./shopping');
+const { MealieError } = require('./mealie');
+
+function createApp({ db, mealie }) {
+  const insertPlan = db.prepare('INSERT INTO plans (id, week_start) VALUES (?, ?)');
+  const insertMeal = db.prepare('INSERT INTO plan_meals (plan_id, day_index, date, meal_index, slot, recipe_slug, recipe_name, ingredients) VALUES (?, ?, ?, ?, ?, ?, ?, ?)');
+  const getPlan = db.prepare('SELECT id, week_start FROM plans WHERE id = ?');
+  const getMeals = db.prepare('SELECT * FROM plan_meals WHERE plan_id = ? ORDER BY day_index, meal_index');
+
+  function readPlan(id) {
+    const p = getPlan.get(id);
+    if (!p) return null;
+    const days = [];
+    for (const m of getMeals.all(id)) {
+      if (!days[m.day_index]) days[m.day_index] = { date: m.date, meals: [] };
+      days[m.day_index].meals.push({ slot: m.slot, recipeSlug: m.recipe_slug, recipeName: m.recipe_name });
+    }
+    return { id: p.id, weekStart: p.week_start, days };
+  }
+
+  async function createPlan(body) {
+    const req = validateRequest(body);
+    const schedule = buildSchedule(req, await mealie.listRecipes());
+    const details = new Map();
+    for (const d of schedule) {
+      for (const m of d.meals) {
+        if (!details.has(m.recipe.slug)) details.set(m.recipe.slug, await mealie.getRecipe(m.recipe.slug));
+      }
+    }
+    const id = randomUUID();
+    db.transaction(() => {
+      insertPlan.run(id, body.weekStart);
+      schedule.forEach((d, di) => d.meals.forEach((m, mi) => {
+        const ings = details.get(m.recipe.slug).recipeIngredient || [];
+        insertMeal.run(id, di, d.date, mi, m.slot, m.recipe.slug, m.recipe.name, JSON.stringify(ings));
+      }));
+    })();
+    return readPlan(id);
+  }
+
+  function shoppingList(id) {
+    if (!getPlan.get(id)) return null;
+    const ings = getMeals.all(id).flatMap((m) => JSON.parse(m.ingredients));
+    return { planId: id, ...buildShoppingList(ings) };
+  }
+
+  async function readBody(req) {
+    const chunks = [];
+    for await (const c of req) chunks.push(c);
+    try {
+      return JSON.parse(Buffer.concat(chunks).toString('utf8'));
+    } catch (e) {
+      throw new ValidationError('body must be valid JSON');
+    }
+  }
+
+  async function route(req, send) {
+    const path = new URL(req.url, 'http://x').pathname.replace(/\/+$/, '') || '/';
+    let m;
+    if (path === '/health' && req.method === 'GET') return send(200, { ok: true });
+    if (path === '/plans' && req.method === 'POST') return send(201, await createPlan(await readBody(req)));
+    if ((m = path.match(/^\/plans\/([^/]+)$/)) && req.method === 'GET') {
+      const p = readPlan(decodeURIComponent(m[1]));
+      return p ? send(200, p) : send(404, { error: 'plan not found' });
+    }
+    if ((m = path.match(/^\/plans\/([^/]+)\/shopping-list$/)) && req.method === 'GET') {
+      const l = shoppingList(decodeURIComponent(m[1]));
+      return l ? send(200, l) : send(404, { error: 'plan not found' });
+    }
+    return send(404, { error: 'not found' });
+  }
+
+  return http.createServer(async (req, res) => {
+    const send = (code, body) => {
+      res.writeHead(code, { 'content-type': 'application/json' });
+      res.end(JSON.stringify(body));
+    };
+    try {
+      await route(req, send);
+    } catch (e) {
+      if (e instanceof ValidationError) send(400, { error: e.message });
+      else if (e instanceof NoRecipesError) send(409, { error: e.message });
+      else if (e instanceof MealieError) send(502, { error: e.message });
+      else send(500, { error: 'internal error' });
+    }
+  });
+}
+
+module.exports = { createApp };
diff --git a/src/db.js b/src/db.js
new file mode 100644
index 0000000..26a1d77
--- /dev/null
+++ b/src/db.js
@@ -0,0 +1,30 @@
+'use strict';
+const fs = require('fs');
+const path = require('path');
+const Database = require('better-sqlite3');
+
+const MIGRATIONS_DIR = path.join(__dirname, '..', 'migrations');
+
+function openDatabase(file) {
+  const db = new Database(file);
+  db.pragma('journal_mode = WAL');
+  db.pragma('foreign_keys = ON');
+  migrate(db);
+  return db;
+}
+
+function migrate(db) {
+  db.exec("CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT (datetime('now')))");
+  const applied = new Set(db.prepare('SELECT name FROM schema_migrations').all().map((r) => r.name));
+  const files = fs.readdirSync(MIGRATIONS_DIR).filter((f) => /^\d+_.+\.sql$/.test(f)).sort();
+  for (const f of files) {
+    if (applied.has(f)) continue;
+    const sql = fs.readFileSync(path.join(MIGRATIONS_DIR, f), 'utf8');
+    db.transaction(() => {
+      db.exec(sql);
+      db.prepare('INSERT INTO schema_migrations (name) VALUES (?)').run(f);
+    })();
+  }
+}
+
+module.exports = { openDatabase };
