@@ -0,0 +1,42 @@
+'use strict';
+
+class MealieError extends Error {}
+
+function createMealieClient(baseUrl) {
+  const base = String(baseUrl || '').replace(/\/+$/, '');
+
+  async function getJson(pathAndQuery) {
+    let res;
+    try {
+      res = await fetch(base + pathAndQuery);
+    } catch (e) {
+      throw new MealieError(`Mealie unreachable: ${e.message}`);
+    }
+    if (!res.ok) throw new MealieError(`Mealie responded ${res.status} for ${pathAndQuery}`);
+    try {
+      return await res.json();
+    } catch (e) {
+      throw new MealieError(`Mealie returned invalid JSON for ${pathAndQuery}`);
+    }
+  }
+
+  // Pages may hold fewer items than asked for, so follow total_pages.
+  async function listRecipes() {
+    const out = [];
+    for (let page = 1; ; page++) {
+      const body = await getJson(`/api/recipes?page=${page}&perPage=100`);
+      const items = Array.isArray(body.items) ? body.items : [];
+      out.push(...items);
+      if (!items.length || page >= (Number(body.total_pages) || 1)) break;
+    }
+    return out;
+  }
+
+  function getRecipe(slug) {
+    return getJson(`/api/recipes/${encodeURIComponent(slug)}`);
+  }
+
+  return { listRecipes, getRecipe };
+}
+
+module.exports = { createMealieClient, MealieError };
diff --git a/src/planner.js b/src/planner.js
new file mode 100644
