--- /dev/null
+++ b/src/planner.js
@@ -0,0 +1,79 @@
+'use strict';
+
+const SLOTS = { 1: ['dinner'], 2: ['lunch', 'dinner'], 3: ['breakfast', 'lunch', 'dinner'] };
+
+class ValidationError extends Error {}
+class NoRecipesError extends Error {}
+
+const isInt = (v) => typeof v === 'number' && Number.isInteger(v);
+
+function parseDate(s) {
+  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
+  const d = new Date(`${s}T00:00:00Z`);
+  if (Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== s) return null;
+  return d;
+}
+
+function tagList(v, name) {
+  if (v === undefined) return [];
+  if (!Array.isArray(v) || v.some((t) => typeof t !== 'string')) throw new ValidationError(`${name} must be an array of strings`);
+  return v;
+}
+
+function validateRequest(body) {
+  if (body === null || typeof body !== 'object' || Array.isArray(body)) throw new ValidationError('body must be a JSON object');
+  const start = parseDate(body.weekStart);
+  if (!start) throw new ValidationError('weekStart must be a valid date (YYYY-MM-DD)');
+  if (start.getUTCDay() !== 1) throw new ValidationError('weekStart must be a Monday');
+  const days = body.days === undefined ? 7 : body.days;
+  if (!isInt(days) || days < 1 || days > 14) throw new ValidationError('days must be an integer from 1 to 14');
+  const r = body.rules === undefined ? {} : body.rules;
+  if (r === null || typeof r !== 'object' || Array.isArray(r)) throw new ValidationError('rules must be an object');
+  const mealsPerDay = r.mealsPerDay === undefined ? 1 : r.mealsPerDay;
+  if (!isInt(mealsPerDay) || mealsPerDay < 1 || mealsPerDay > 3) throw new ValidationError('mealsPerDay must be an integer from 1 to 3');
+  const includeTags = tagList(r.includeTags, 'includeTags');
+  const excludeTags = tagList(r.excludeTags, 'excludeTags');
+  const max = r.maxTotalTimeMinutes === undefined ? null : r.maxTotalTimeMinutes;
+  if (max !== null && (typeof max !== 'number' || !Number.isFinite(max) || max < 0)) throw new ValidationError('maxTotalTimeMinutes must be a non-negative number or null');
+  return { start, days, mealsPerDay, includeTags, excludeTags, max };
+}
+
+// ISO 8601 duration -> minutes, or null when absent/unparseable.
+function durationMinutes(s) {
+  if (typeof s !== 'string') return null;
+  const m = s.match(/^P(?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?$/);
+  if (!m || s === 'P' || s.endsWith('T')) return null;
+  const [w, d, h, min, sec] = m.slice(1).map((x) => (x === undefined ? 0 : Number(x)));
+  return w * 10080 + d * 1440 + h * 60 + min + sec / 60;
+}
+
+function eligible(recipes, { includeTags, excludeTags, max }) {
+  return recipes
+    .filter((r) => {
+      const slugs = new Set((r.tags || []).map((t) => t.slug));
+      if (!includeTags.every((t) => slugs.has(t))) return false;
+      if (excludeTags.some((t) => slugs.has(t))) return false;
+      if (max !== null) {
+        const mins = durationMinutes(r.totalTime);
+        if (mins === null || mins > max) return false;
+      }
+      return true;
+    })
+    .sort((a, b) => (a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0));
+}
+
+// Returns [{date, meals: [{slot, recipe}]}].
+function buildSchedule(req, recipes) {
+  const pool = eligible(recipes, req);
+  if (!pool.length) throw new NoRecipesError('no eligible recipes');
+  const slots = SLOTS[req.mealsPerDay];
+  let n = 0;
+  const days = [];
+  for (let i = 0; i < req.days; i++) {
+    const date = new Date(req.start.getTime() + i * 86400000).toISOString().slice(0, 10);
+    days.push({ date, meals: slots.map((slot) => ({ slot, recipe: pool[n++ % pool.length] })) });
+  }
+  return days;
+}
+
+module.exports = { validateRequest, buildSchedule, durationMinutes, ValidationError, NoRecipesError };
