@@ -0,0 +1,45 @@
+'use strict';
+
+const MASS = { g: 1, kg: 1000 };
+const VOLUME = { ml: 1, l: 1000, tsp: 5, tbsp: 15, cup: 240 };
+const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
+const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
+
+function classify(unit) {
+  const abbr = unit && typeof unit.abbreviation === 'string' ? unit.abbreviation.trim() : '';
+  if (!unit) return { kind: 'count' };
+  if (!abbr) return { kind: 'count' };
+  if (Object.hasOwn(MASS, abbr)) return { kind: 'mass', factor: MASS[abbr] };
+  if (Object.hasOwn(VOLUME, abbr)) return { kind: 'volume', factor: VOLUME[abbr] };
+  return { kind: 'other', abbr };
+}
+
+// ingredients: flat array of Mealie recipeIngredient entries (one per planned occurrence).
+function buildShoppingList(ingredients) {
+  const sums = new Map();
+  const notes = new Set();
+  for (const ing of ingredients) {
+    const name = ing.food && typeof ing.food.name === 'string' ? ing.food.name.trim().toLowerCase() : '';
+    if (!name) {
+      if (typeof ing.note === 'string' && ing.note.trim()) notes.add(ing.note);
+      continue;
+    }
+    const qty = typeof ing.quantity === 'number' ? ing.quantity : 1;
+    const c = classify(ing.unit);
+    const base = c.kind === 'mass' || c.kind === 'volume' ? qty * c.factor : qty;
+    const unitKey = c.kind === 'other' ? `other:${c.abbr}` : c.kind;
+    const k = JSON.stringify([name, unitKey]);
+    const e = sums.get(k) || { food: name, c, total: 0 };
+    e.total += base;
+    sums.set(k, e);
+  }
+  const items = [...sums.values()].map(({ food, c, total }) => {
+    if (c.kind === 'mass') return total < 1000 ? { food, quantity: round2(total), unit: 'g' } : { food, quantity: round2(total / 1000), unit: 'kg' };
+    if (c.kind === 'volume') return total < 1000 ? { food, quantity: round2(total), unit: 'ml' } : { food, quantity: round2(total / 1000), unit: 'l' };
+    return { food, quantity: round2(total), unit: c.kind === 'other' ? c.abbr : null };
+  });
+  items.sort((a, b) => cmp(a.food, b.food) || (a.unit === b.unit ? 0 : a.unit === null ? -1 : b.unit === null ? 1 : cmp(a.unit, b.unit)));
+  return { items, notes: [...notes].sort(cmp) };
+}
+
+module.exports = { buildShoppingList };
