+
+const ing = (food, quantity, abbreviation, note = '') => ({
+  quantity,
+  unit: abbreviation === null ? null : { name: abbreviation, abbreviation },
+  food: food === null ? null : { name: food },
+  note,
+});
+
+test('mass units merge case-insensitively and switch to kg at 1000 g', () => {
+  const r = buildShoppingList([ing('Flour', 600, 'g'), ing('flour', 0.5, 'kg'), ing('rice', 250, 'g')]);
+  assert.deepStrictEqual(r.items, [
+    { food: 'flour', quantity: 1.1, unit: 'kg' },
+    { food: 'rice', quantity: 250, unit: 'g' },
+  ]);
+});
+
+test('volume units convert to ml and l', () => {
+  const r = buildShoppingList([ing('milk', 1, 'cup'), ing('milk', 2, 'tbsp'), ing('milk', 1, 'tsp'), ing('oil', 1, 'l'), ing('oil', 500, 'ml')]);
+  assert.deepStrictEqual(r.items, [
+    { food: 'milk', quantity: 275, unit: 'ml' },
+    { food: 'oil', quantity: 1.5, unit: 'l' },
+  ]);
+});
+
+test('counts, null quantity, and other units are separate kinds', () => {
+  const r = buildShoppingList([ing('salt', null, 'pinch'), ing('salt', 2, 'pinch'), ing('salt', 1, 'g'), ing('salt', null, null), ing('salt', 2, null)]);
+  assert.deepStrictEqual(r.items, [
+    { food: 'salt', quantity: 3, unit: null },
+    { food: 'salt', quantity: 1, unit: 'g' },
+    { food: 'salt', quantity: 3, unit: 'pinch' },
+  ]);
+});
+
+test('ingredients without food go to sorted, de-duplicated notes', () => {
+  const r = buildShoppingList([ing(null, 1, null, 'zest'), ing(null, 1, null, 'a bit of love'), ing(null, null, null, 'zest')]);
+  assert.deepStrictEqual(r.items, []);
+  assert.deepStrictEqual(r.notes, ['a bit of love', 'zest']);
+});
+
+test('quantities are rounded to 2 decimals', () => {
+  const r = buildShoppingList([ing('x', 0.333, null), ing('x', 0.333, null), ing('x', 0.333, null)]);
+  assert.strictEqual(r.items[0].quantity, 1);
+  assert.strictEqual(buildShoppingList([ing('y', 1 / 3, null)]).items[0].quantity, 0.33);
+});
+
+test('durations parse to minutes', () => {
+  assert.strictEqual(durationMinutes('PT45M'), 45);
+  assert.strictEqual(durationMinutes('PT1H20M'), 80);
+  assert.strictEqual(durationMinutes(null), null);
+  assert.strictEqual(durationMinutes('soon'), null);
+});

